algorithms.pseudocode:
function NerodePartition(A, max_depth):
    for each state q in Q:
        sig[q] = ()
    for d = 0, 1, ..., max_depth:
        for each suffix w of length d:
            for each state q in Q:
                sig[q] = sig[q] ++ (out(delta_hat(q, w)),)
        partition = group states by sig
        if partition unchanged: return partition
    return partition

function BuildNerodeAutomaton(A):
    P = NerodePartition(A)
    for each class C in P:
        choose representative rep(C)
        out_N(C) = out(rep(C))
        for each a in Sigma:
            delta_N(C, a) = P[delta(rep(C), a)]
    init_N = P[q_0]
    return (P, Sigma, delta_N, init_N, out_N)
